const snapshot = {"sourceVersion":"sqlite-0.1","generatedAt":"2026-09-11T10:12:36+00:00","manifestVersion":"0.1","records":[{"kind":"entry","version":"sqlite-0.1","record":{"slug":"броня","kind":"article","entry":{"lemma":"броня","url_slug":"броня","gloss":"металевий одяг для захисту тулуба воїна","pos":"noun","ipa":null,"primary_source":"content_lexicon_grow","course_usage":[{"track":"b1","module_num":32,"slug":"verb-formation-suffixes","context":"content_backfill"}],"heritage_status":{"classification":"standard","attestations":[{"source":"VESUM","ref":"броня","detail":"lemma match (14 forms)"}],"is_russianism":false,"russian_shadow":false,"vesum_attested":true,"calque_warning":null,"warning_severity":"treasured"},"enrichment":{"stress":{"form":"броня́","source":"kaikki/Wiktionary (CC BY-SA 3.0)","ipa":"[brɔˈnʲa]"},"cefr":{"level":"B2","source":"estimated (GRAC frequency)","text":"B2 (орієнтовно / estimated; GRAC 0.55/million, rank 2792/4161)"},"morphology":{"pos":"іменник","form_count":14,"forms":[{"form":"броні","label":"жін., давальний","stress":"бро́ні"},{"form":"броне","label":"жін., кличний","stress":"бро́не"},{"form":"броні","label":"жін., місцевий","stress":"бро́ні"},{"form":"броня","label":"жін., називний"},{"form":"бронею","label":"жін., орудний"},{"form":"броні","label":"жін., родовий","stress":"бро́ні"},{"form":"броню","label":"жін., знахідний"},{"form":"броням","label":"множина, давальний","stress":"бро́ням"},{"form":"броні","label":"множина, кличний","stress":"бро́ні"},{"form":"бронях","label":"множина, місцевий","stress":"бро́нях"},{"form":"броні","label":"множина, називний","stress":"бро́ні"},{"form":"бронями","label":"множина, орудний","stress":"бро́нями"},{"form":"бронь","label":"множина, родовий"},{"form":"броні","label":"множина, знахідний","stress":"бро́ні"}],"source":"VESUM","paradigm":{"kind":"noun","cases":{"називний":{"singular":"броня","plural":"броні"},"родовий":{"singular":"броні","plural":"бронь"},"давальний":{"singular":"броні","plural":"броням"},"знахідний":{"singular":"броню","plural":"броні"},"орудний":{"singular":"бронею","plural":"бронями"},"місцевий":{"singular":"броні","plural":"бронях"},"кличний":{"singular":"броне","plural":"броні"}}},"stress":{"source":"ukrainian-word-stress","forms":{"броні":"бро́ні","броне":"бро́не","броням":"бро́ням","бронях":"бро́нях","бронями":"бро́нями"}}},"meaning":{"definitions":["металевий одяг для захисту тулуба воїна","захисне облицювання із сталевих плит на військових кораблях, поїздах, автомобілях і т. ін","роньовані бойові машини"],"source":"Вікісловник"},"definition_cards":[{"id":"vts","source":"ВТС","source_pill":"ВТС","note":"Великий тлумачний словник сучасної української мови","definitions":["бро́н я бр о н і , ж. 1》 заст. Металевий одяг для воїна. || Зброя. 2》 Захисне облицювання із сталевих плит на військових кораблях, поїздах, автомобілях і т. ін. || Броньовані бойові машини. 3》 тільки брон я . Закріплення когось або чогось за ким-, чим-небудь; документ на це закріплення."],"source_url":"https://slovnyk.me/dict/vts/%D0%B1%D1%80%D0%BE%D0%BD%D1%8F"},{"id":"sum20","source":"СУМ-20","source_pill":"СУМ-20","note":"сучасний тлумачний словник","definitions":["БРОНЯ́, і́, ж. 1. заст. Металевий одяг для захисту тіла воїна. Вже зібрався Олег віщий На вражу недолю, Їде конем білогривим По чистому полю. Блищить броня цареградська, Шелом аж палає (С. Руданський); Підталий на весняному сонці лід затріщав під вагою одягнених у броню лицарів (з навч. літ.); * Образно. Стійте, підперезавши стегна свої правдою і зодягнувшись у броню праведності (Біблія. Пер. І. Огієнка); * У порівн. А кінь .. як намальований: шерсть на йому блищить, як броня (О. Стороженко); // Зброя. У той день, як нам рушать, подарував він свого коня і роздав броню: кому шаблю, кому пістолі, кому гвинтівку (О. Стороженко); До броні! Настала година слушна За рідний край стать в обороні (М. Старицький). 2. Захисне облицювання зі сталевих плит на військових кораблях, поїздах, автомобілях і т. ін. Вони бронепоїзди обшивали корабельною бронею (В. Кучер); Де бронею танки в просторах гриміли, комбайни в житах попливуть (В. Сосюра); Лише після Синопської битви 30 листопада 1853 р. стало очевидно: дерев'яні кораблі без броні надто приступні для нападу (із журн.); // Броньовані бойові машини. Вони чекали тієї хвилини, коли, сівши на броню, ринуться в прорив (Ю. Яновський). 3. перен. Панцир, що вкриває тіло деяких тварин. Броненосці з'явилися на Землі приблизно 55 мільйонів років тому, а вижити їм допомогла та сама броня, від якої і пішла їхня назва (з наук.-попул. літ.). БРО́НЯ, і, ж. 1. Офіційне закріплення за ким-, чим-небудь пільгових прав на користування чим-небудь, отримання чого-небудь, а також документ на таке закріплення. Дивні звичаї! А ще дивніший цей поїзд. На нього не треба було ані броні, ані квитків (І. Багряний). 2. Закріплення кого-небудь за певним закладом, яке звільняє його від служби в армії, а також документ на таке закріплення. – Всю війну я провів у Казахстані .. З бронею в кишені просиджую штани у заводській лабораторії (Н. Рибак); Студенти поки що можуть спати спокійно – у них броня до закінчення університету (О. Гончар)."],"source_url":"https://slovnyk.me/dict/newsum/%D0%B1%D1%80%D0%BE%D0%BD%D1%8F"}],"etymology":{"text":"Inherited from Old East Slavic брънꙗ (brŭnja), from Proto-Slavic *brъňa, from Gothic 𐌱𐍂𐌿𐌽𐌾𐍉 (brunjō, “breastplate”), from Proto-Germanic *brunjǭ (“breastplate”). Same as etymology 1, the meanings derive from Russian бро́ня (brónja, “reservation”).","source":"kaikki/Wiktionary (CC BY-SA 3.0)"},"literary_attestation":{"text":"…ву — невблаганно повзуче — рушили докупи, і саме тоді, коли вони нарешті зійшлися, він устиг пальнути кілька разів. Але двері виявилися, на щастя, куленепробивними. Хороша танкова броня часів \"усе для фронту і для перемоги\". І ліфт, на щастя, поїхав. Певний час до тебе долітало завивання якоїсь сирени, потім були вигуки, біганина в коридорах. Ці звуки приходили з…","source":"literary_fts","source_label":"Андрухович Ю. · Юрій Андрухович. Московіада · 1960","chunk_id":"e27925aa_c0131","source_url":""},"translation":{"en":["reservation, booking","deferment (from conscription)","armor (protective layer over a body, vehicle, or other object intended to deflect or diffuse damaging forces)","(military) armor, armour, armoring","(military) armored vehicle, armored car (collective or in the singular)","shell (of animals)"],"source":"dmklinger","pos":"noun"},"sources":["VESUM","dmklinger","estimated (GRAC frequency)","kaikki/Wiktionary (CC BY-SA 3.0)","literary_fts","ВТС","Вікісловник","Орфографічний словник української мови + Орфоепічний словник української мови","СУМ-20"]},"pronunciation":{"ipa":"[brɔˈnʲa]","source":"kaikki/Wiktionary (CC BY-SA 3.0)"},"sections":{"synonyms":{"source":"Ukrajinet WordNet: gated synset → кольчуга","items":["кольчуга"]},"form_notes":{"items":[{"dictionary":"orthography","text":"бро́ня іменник жіночого роду закріплення; документ про закріплення броня́ іменник жіночого роду захисна обшивка","source":"Орфографічний словник української мови","mirror_source_url":"https://slovnyk.me/dict/orthography/%D0%B1%D1%80%D0%BE%D0%BD%D1%8F"},{"dictionary":"orthoepy","text":"броня́ [брон’а] броун'і, ор. бронейу (захисна обшивка)","source":"Орфоепічний словник української мови","mirror_source_url":"https://slovnyk.me/dict/orthoepy/%D0%B1%D1%80%D0%BE%D0%BD%D1%8F"}],"source":"Орфографічний словник української мови + Орфоепічний словник української мови","mirror_source_urls":["https://slovnyk.me/dict/orthography/%D0%B1%D1%80%D0%BE%D0%BD%D1%8F","https://slovnyk.me/dict/orthoepy/%D0%B1%D1%80%D0%BE%D0%BD%D1%8F"]}},"entry_type":"lemma"},"aliases":[{"alias":"bronia","kind":"transliteration","source":"migration","target_slug":"броня"}],"relations":[],"provenance":[{"source_family":"content_lexicon_grow","source_locator":null,"extraction_mode":null}],"renderContext":{"componentLinks":[],"practiceLevels":["B2"]}}},{"kind":"entry","version":"sqlite-0.1","record":{"slug":"ключ","kind":"article","entry":{"lemma":"ключ","url_slug":"ключ","gloss":"key","pos":"noun","ipa":null,"primary_source":"built_vocabulary","course_usage":[{"track":"a1","module_num":8,"slug":"things-have-gender","context":"built_vocabulary"},{"track":"a2","module_num":5,"slug":"genitive-intro","context":"built_vocabulary"},{"track":"b1","module_num":56,"slug":"instrumental-nuances","context":"built_vocabulary"},{"track":"b1","module_num":17,"slug":"noun-subclasses-hissing","context":"built_vocabulary"}],"heritage_status":{"classification":"standard","attestations":[{"source":"VESUM","ref":"ключ","detail":"lemma match (18 forms)"}],"is_russianism":false,"russian_shadow":false,"vesum_attested":true,"calque_warning":null,"warning_severity":"treasured"},"pronunciation":{"ipa":"[klʲut͡ʃ]","source":"kaikki/Wiktionary (CC BY-SA 3.0)"},"sections":{"synonyms":{"items":["відмикачка"],"source":"slovnyk.me: Словник синонімів Караванського","source_urls":["https://slovnyk.me/dict/synonyms_karavansky/%D0%BA%D0%BB%D1%8E%D1%87"]},"idioms":{"items":[{"text":"бити ключем (джерелом, фонтаном і т","phrase":"бити ключем (джерелом, фонтаном і т","definition":"ін ). 1. Виявлятися на всю силу, великою мірою. Дійсно був красень (опришок). Сила тремтючим потоком переливалася в жилах, била ключем (Г. Хоткевич); Музична стихія .. чаклунського слова Тичини била ключем з усього, до чого б не доторкалася його увага (Т. Масенко); Скрізь на рідній землі б’є джерелом творча енергія народних мас (З газети); Кінотеатрів тут два, Поліклініка є... Магазинів усяких багато. Фонтаном життя у Мальованім б’є У будень і в свято (С. Воскрекасенко). 2. Здійснюватися, відбуватися і т. ін. дуже енергійно, інтенсивно. Знову гора обізвалась, загула: з губернії приїхав будівничий, ціла артіль.., брязкіт сокир,— робота ключем…","source":"Фразеологічний словник української мови","source_url":"https://slovnyk.me/dict/phraseology/%D0%BA%D0%BB%D1%8E%D1%87"},{"text":"бити ключем (джерелом і т.ін.) 1","phrase":"бити ключем (джерелом і т.ін.) 1","definition":"Виявлятися на всю силу, великою мірою; здійснюватися у всіх проявах. Дійсно був красень опришок. Сила тремтючим потоком переливалася в жилах, била ключем (Г. Хоткевич); Музична стихія… чаклунського слова Тичини била ключем з усього, до чого б не доторкалася його увага (Т. Масенко); Скрізь на рідній землі б'є джерелом творча енергія народних мас (З газети); Кінотеатрів тут два, Поліклініка є… Магазинів усяких багато. Фонтаном життя у Мальованім б'є У будень і в свято (С. Воскрекасенко). 2. Здійснюватися, відбуватися і т.ін. дуже енергійно, інтенсивно. Знову гора обізвалась, загула: з губернії приїхав будівничий, ціла артіль.., брязкіт сокир,—…","source":"Фразеологічний словник","source_url":""},{"text":"підбирати (знаходити) / підібрати (знайти) ключ (ключа) до кого--чого","phrase":"підбирати (знаходити) / підібрати (знайти) ключ (ключа) до кого--чого","definition":"Знаходити певний спосіб розгадування, розв'язання і т.ін. чогось. Учених, котрі десятиріччями б'ються над загадками нерозшифрованих написів, не полишає віра, що вони врешті таки підберуть до них ключа (Н. Тихий). підбирати ключик. Радянські закони якраз і допомагають до будь-якої людини підбирати ключик, орієнтуючись на приклади ставлення до праці (З газети).","source":"Фразеологічний словник","source_url":""},{"text":"давати / дати ключ у руки кому","phrase":"давати / дати ключ у руки кому","definition":"Сприяти ясності, доступності, допомагати зрозуміти що-небудь. Побут у його селі дав мені ключ до розуміння його вдачі (І. Франко); Ми не відривалися від зусиль його розуму вимовити ще щось, що дало б нам ключ, хто він є — цей бурлака з моря (Ю. Яновський). давати в руки ключ. Ідейна концепція твору, посилена емоційним ставленням постановників до зображуваного, дає їм в руки той ключ, за допомогою якого вишукується образ спектаклю (З журналу).","source":"Фразеологічний словник","source_url":""}],"source":"slovnyk.me: Фразеологічний словник української мови + Фразеологічний словник української мови","source_urls":["https://slovnyk.me/dict/phraseology/%D0%BA%D0%BB%D1%8E%D1%87"]}},"enrichment":{"stress":{"form":"клю́ч","source":"kaikki/Wiktionary (CC BY-SA 3.0)","ipa":"[klʲut͡ʃ]"},"cefr":{"level":"A2","source":"PULS CEFR","pos":"іменник","text":"ключ (A2, іменник)"},"morphology":{"pos":"іменник","form_count":18,"forms":[{"form":"ключеві","label":"чол., давальний","stress":"ключе́ві"},{"form":"ключу","label":"чол., давальний"},{"form":"ключу","label":"чол., кличний"},{"form":"ключеві","label":"чол., місцевий","stress":"ключе́ві"},{"form":"ключі","label":"чол., місцевий","stress":"ключі́"},{"form":"ключу","label":"чол., місцевий"},{"form":"ключ","label":"чол., називний"},{"form":"ключем","label":"чол., орудний","stress":"ключе́м"},{"form":"ключа","label":"чол., родовий","stress":"ключа́"},{"form":"ключ","label":"чол., знахідний"},{"form":"ключа","label":"чол., знахідний","stress":"ключа́"},{"form":"ключам","label":"множина, давальний","stress":"ключа́м"},{"form":"ключі","label":"множина, кличний","stress":"ключі́"},{"form":"ключах","label":"множина, місцевий","stress":"ключа́х"},{"form":"ключі","label":"множина, називний","stress":"ключі́"},{"form":"ключами","label":"множина, орудний","stress":"ключа́ми"},{"form":"ключів","label":"множина, родовий","stress":"ключі́в"},{"form":"ключі","label":"множина, знахідний","stress":"ключі́"}],"source":"VESUM","paradigm":{"kind":"noun","cases":{"називний":{"singular":"ключ","plural":"ключі"},"родовий":{"singular":"ключа","plural":"ключів"},"давальний":{"singular":"ключеві / ключу","plural":"ключам"},"знахідний":{"singular":"ключ / ключа","plural":"ключі"},"орудний":{"singular":"ключем","plural":"ключами"},"місцевий":{"singular":"ключеві / ключі / ключу","plural":"ключах"},"кличний":{"singular":"ключу","plural":"ключі"}}},"stress":{"source":"ukrainian-word-stress","forms":{"ключеві":"ключе́ві","ключі":"ключі́","ключем":"ключе́м","ключа":"ключа́","ключам":"ключа́м","ключах":"ключа́х","ключами":"ключа́ми","ключів":"ключі́в","ключеві / ключу":"ключе́ві / ключу","ключ / ключа":"ключ / ключа́","ключеві / ключі / ключу":"ключе́ві / ключі́ / ключу"}}},"meaning":{"definitions":["key","wrench, spanner, screw wrench","clue, key","clef, key","radical (in Chinese characters)"],"source":"kaikki/Wiktionary (CC BY-SA 3.0)","note":"English Wiktionary gloss fallback; direct per-lemma row."},"definition_cards":[{"id":"vts","source":"ВТС","source_pill":"ВТС","note":"Великий тлумачний словник сучасної української мови","definitions":["I - а , ч. 1》 Знаряддя для замикання та відмикання замка, засува та ін. Під ключ (здав а ти, зд а ти що ) — в остаточному, завершеному вигляді. 2》 Інструмент для загвинчування або відгвинчування гайок, болтів і т. ін. Гайковий ключ . Накидний ключ . Рожковий ключ . 3》 Двополюсний перемикальний елемент електричного кола. Телеграфний ключ . 4》 до чого , для чого , перен. Засіб для розуміння, розгадування когось, чогось, для оволодіння чимось. Підібр а ти ключ (ключ і ) до кого-, чого-небудь — зрозуміти сутність кого-, чого-небудь, знайти правильний підхід до кого-, чого-небудь. У ключ і якому (напис а ти, зобраз и ти, показ а ти і т. ін. кого-, що-небудь ) — у якому-небудь плані, стилі, манері і т. ін. || Умовна система позначення літер, цифр і т. ін., на якій засновано спосіб читання якого-небудь шифрованого тексту. || Підрядник до іноземного тексту, а також збірник відповідей на задачі.…"],"source_url":"https://slovnyk.me/dict/vts/%D0%BA%D0%BB%D1%8E%D1%87"},{"id":"sum20","source":"СУМ-20","source_pill":"СУМ-20","note":"сучасний тлумачний словник","definitions":["КЛЮЧ ¹ , а́, ч. 1 . Металевий стрижень з особливою комбінацією вирізів для замикання та відмикання замка. Сторож брязнув ключами, одмикаючи важкий здоровий замок (І. Нечуй-Левицький); Тремтяча рука довго не могла попасти ключем у дірку, щоб відімкнути двері від покою (І. Франко); Довго крутиться в замку ключ. Двері відчиняються (В. Винниченко); Раптом у коридорі нервово задзвеніли ключі, заскреготав замок (К. Гриб); Миколка кинувся до замка, довго не потрапляв ключем (М. Вінграновський); // Спеціальний стрижень для введення в дію автомобіля, мотоцикла і т. ін. Зараз же вiдступає [Юркевич] злякано, бачачи доктора Карфункеля, що стоїть на дверях i тихо смiється, накручуючи ключем годинника (І. Кочерга); Біля машини зчинилася метушня, знову чулася лайка, мотор не заводився, десь ключ загубили в соборі... (О. Гончар); Він кидався то до ключа запалювання, то до мотора, шарпав за проводи, сту…"],"source_url":"https://slovnyk.me/dict/newsum/%D0%BA%D0%BB%D1%8E%D1%87"}],"etymology":{"text":"пов’язання з нвн. Krücke «милиця» (Machek ESJČ 256) викликає сумнів; іє. *(s)kleu- : *klau- «гак, крюк, ковінька; зачепити; заперти, замкнути»; псл. kljukati «клювати; рубати», kljuka «закривлений дрюк, крюк»; споріднене з лит. kliuti «зависнути, зачепитися», лтс. klaût «нахиляти, нагинати», лат. clāvis «ключ; дрюк; засув», сlāvus «гвіздок», гр. κλείς «засув, ключ», κλείω «запираю, засуваю», дірл. clō «гвіздок», а також н. Schlüssel «ключ», двн. slioƷban «запирати»; р. [ клюка́ть ] «ходити з палицею, кульгати», [ клю́чить ] « тс. », клюка́ «ломака, ковінька», п. kluka «дрюк з гаком, ключ у кол","source":"Горох (за ЕСУМ)","source_url":"https://goroh.pp.ua/%D0%95%D1%82%D0%B8%D0%BC%D0%BE%D0%BB%D0%BE%D0%B3%D1%96%D1%8F/%D0%BA%D0%BB%D1%8E%D1%87"},"literary_attestation":{"text":"…к зовсім конкретну вказівку, якої він у поспіху не розчовпав. Кожного разу, як він повертався до цього вигуку, його пронизував здогад, що Гнат через голови клунь подавав йому тоді ключ до подій, те чарівне слово, за допомогою якого знаходять скарби, яке виповнює людину заклинальною силою, уможливлюючи їй вмить гідно витримати найтяжчі випробування серед злих дух…","source":"literary_fts","source_label":"Андієвська Е. · Емма Андієвська. Роман про добру людину · 1931","chunk_id":"e4b5541c_c0150","source_url":""},"translation":{"en":["key","wrench, spanner, screw wrench","keystone (the top stone of an arch)","switch (device to turn electric current on and off)"],"source":"learner_english_gloss","pos":"noun"},"sources":["Anna Ohoiko","PULS CEFR","VESUM","dmklinger","kaikki/Wiktionary (CC BY-SA 3.0)","learner_english_gloss","literary_fts","slovnyk.me: Словник синонімів Караванського","slovnyk.me: Фразеологічний словник української мови + Фразеологічний словник української мови","ВТС","Горох (за ЕСУМ)","СУМ-20"],"examples":[{"uk":"Де ключ від кварти́ри?","en":"Where is the key to the apartment?","source":"Anna Ohoiko","locator":"ohoiko-1000-words entry 354"}]},"gate_provenance":{"homonyms":"source-withdrawn-unverified","enrichment.sources":"source-withdrawn-unverified"},"entry_type":"lemma"},"aliases":[{"alias":"kliuch","kind":"transliteration","source":"migration","target_slug":"ключ"}],"relations":[],"provenance":[{"source_family":"built_vocabulary","source_locator":null,"extraction_mode":null}],"renderContext":{"componentLinks":[],"practiceLevels":["A2"]}}},{"kind":"entry","version":"sqlite-0.1","record":{"slug":"вряди-годи","kind":"article","entry":{"lemma":"вряди-годи","url_slug":"вряди-годи","gloss":"Зрідка, нечасто, деколи. Вони були щирі товаришки, яких тільки вряди-годи зводить життя докупи (Мирний, II, 1954, 256); Вряди-годи проходив хтось тінню по широкій, колись гомінк...","pos":"adverb","ipa":null,"primary_source":"source_inventory_grow","course_usage":[],"heritage_status":{"classification":"standard","attestations":[{"source":"VESUM","ref":"вряди-годи","detail":"lemma match (1 forms)"}],"is_russianism":false,"russian_shadow":false,"vesum_attested":true,"calque_warning":null,"warning_severity":"treasured"},"source_provenance":[{"inventory_path":"data/lexicon/source-inventory/oneshot/textbook-jsonl-curated-2026-07-19-bulk.yaml","source_locator":"6-klas-istoriia-shchupak-2023::6-klas-istoriia-shchupak-2023_s0200","source_id":"textbook-jsonl-curated-2026-07-19-bulk","source_family":"textbook","key":"f13f761bc2f43e09"}],"enrichment":{"stress":{"form":"вряди́-го́ди","source":"ukrainian-word-stress"},"morphology":{"pos":"прислівник","form_count":1,"forms":[{"form":"вряди-годи","label":"","stress":"вряди́-го́ди"}],"source":"VESUM","stress":{"source":"ukrainian-word-stress","forms":{"вряди-годи":"вряди́-го́ди"}}},"literary_attestation":{"text":"Однак мірою того, як ноги теляти міцнили, в його мозку дедалі частіше стали укладатися самі собою не лише круглі, а й продовгасті думки, що своєю пружністю не поступалися м'язам на грудях, і не встиг господар перегнати череду на інше пасовище, як із малого нерозумного теляти викохався кмітливий бичок, на якому вже вряди-годи зупиняли замріяні погляди вологих очей не лише сусідні телички, а й воли, що тяжко працювали в полі.","source":"literary_fts","source_label":"Андієвська Е. · Емма Андієвська. Казка про бика й метелика · 1931","chunk_id":"8e0f6a94_c0000","source_url":""},"sources":["VESUM","literary_fts","ukrainian-word-stress"]},"entry_type":"lemma"},"aliases":[{"alias":"vriady-hody","kind":"transliteration","source":"migration","target_slug":"вряди-годи"}],"relations":[{"related_slug":"часом","entry_type":null,"relation":"synonym","component_role":null,"provenance":"verified"}],"provenance":[{"source_family":"textbook","source_locator":"6-klas-istoriia-shchupak-2023::6-klas-istoriia-shchupak-2023_s0200","extraction_mode":null}],"renderContext":{"componentLinks":[],"practiceLevels":["B1"]}}},{"kind":"entry","version":"sqlite-0.1","record":{"slug":"замок","kind":"article","entry":{"lemma":"замок","url_slug":"замок","gloss":"castle / lock","pos":"noun","ipa":null,"primary_source":"built_vocabulary","course_usage":[{"track":"a1","module_num":4,"slug":"stress-and-melody","context":"built_vocabulary"},{"track":"b1","module_num":29,"slug":"housing-and-renting","context":"built_vocabulary"}],"heritage_status":{"classification":"standard","attestations":[{"source":"VESUM","ref":"замок","detail":"lemma match (33 forms)"}],"is_russianism":false,"russian_shadow":false,"vesum_attested":true,"calque_warning":null,"warning_severity":"treasured"},"pronunciation":{"ipa":"[ˈzamɔk]","source":"kaikki/Wiktionary (CC BY-SA 3.0)"},"sections":{"synonyms":{"items":["фортеця","бастіон","цитадель","шато"],"source":"slovnyk.me: Словник синонімів Караванського","source_urls":["https://slovnyk.me/dict/synonyms_karavansky/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"]},"idioms":{"items":[{"text":"будувати повітряні замки","phrase":"будувати повітряні замки","definition":"Придумувати нездійсненні, відірвані від життя плани, мріяти про щось недосяжне. — Наташко, все буде добре... Ти одужаєш. Я вірю в це.— Платоне, не треба будувати повітряні замки (М. Зарудний). під (за) сімома (трьома) замками, зі сл. тримати, ховати і под. 1. що. Дуже надійно. — Ховають мужицьку правду, за сімома замками ховають, — зітхав хтось біля воріт (М.Стельмах); Добрий господар не той, хто тримає гроші під трьома замками, а той, хто вкладає їх у діло (З газети). 2. Під особливим наглядом, охороною. Він (цар) їх триматиме в полоні під трьома замками (О. Донченко); Зле і кату, зле і жертві, а щасливого нема. Всім судилося померти за зам…","source":"Фразеологічний словник української мови","source_url":"https://slovnyk.me/dict/phraseology/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},{"text":"поцілувати замок (клямку і т.ін.), жарт","phrase":"поцілувати замок (клямку і т.ін.), жарт","definition":"Побачити замкнені двері; нікого не застати десь. Михно: Добре, що застали, ще б годиночку — і поцілували б клямку (О. Кониський); У 120-му кабінеті, де юрмилося багато людей, порадили звернутись до 32-го.. Пошкандибав до 32-го, але й там поцілував замок (З журналу). поцілувати у ломаку. — Приходимо до Христі — аж у неї і хата закручена. Поцілувала Химка у ломаку, та й назад вернулася (Панас Мирний).","source":"Фразеологічний словник","source_url":""},{"text":"рот на замок","phrase":"рот на замок","definition":"Уживається для вираження заборони говорити, розмовляти, про щось розповідати. — З'явишся в Троянівку — рот на замок (Григорій Тютюнник).","source":"Фразеологічний словник","source_url":""}],"source":"slovnyk.me: Фразеологічний словник української мови + Фразеологічний словник української мови","source_urls":["https://slovnyk.me/dict/phraseology/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"]},"form_notes":{"items":[{"dictionary":"orthography","text":"за́мок іменник чоловічого роду будівля замо́к іменник чоловічого роду пристрій для замикання тощо","source":"Орфографічний словник української мови","mirror_source_url":"https://slovnyk.me/dict/orthography/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},{"dictionary":"holoskevych","text":"За́мок, за́мка; за́мки, -мків (будинок) замо́к, -мка́; -мки́, -мкі́в","source":"Правописний словник Голоскевича (1929)","mirror_source_url":"https://slovnyk.me/dict/holoskevych/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},{"dictionary":"orthoepy","text":"I [замок] -мку, м. (на) -мку, мн. -мкие, -мк'іў (будівля) II [замок] -мка, м. (ў) -мку, мн. -мки, -мк'іў (пристрій для замикання тощо)","source":"Орфоепічний словник української мови","mirror_source_url":"https://slovnyk.me/dict/orthoepy/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"}],"source":"Орфографічний словник української мови + Правописний словник Голоскевича (1929) + Орфоепічний словник української мови","mirror_source_urls":["https://slovnyk.me/dict/orthography/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA","https://slovnyk.me/dict/holoskevych/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA","https://slovnyk.me/dict/orthoepy/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"]}},"enrichment":{"stress":{"form":"за́мок","source":"kaikki/Wiktionary (CC BY-SA 3.0)","ipa":"[ˈzamɔk]"},"cefr":{"level":"A2","source":"PULS CEFR","pos":"іменник","text":"замок (A2, іменник)"},"morphology":{"pos":"іменник","form_count":18,"forms":[{"form":"замкові","label":"чол., давальний"},{"form":"замку","label":"чол., давальний","stress":"за́мку"},{"form":"замку","label":"чол., кличний","stress":"за́мку"},{"form":"замкові","label":"чол., місцевий"},{"form":"замку","label":"чол., місцевий","stress":"за́мку"},{"form":"замок","label":"чол., називний"},{"form":"замком","label":"чол., орудний"},{"form":"замка","label":"чол., родовий","stress":"замка́"},{"form":"замку","label":"чол., родовий","stress":"за́мку"},{"form":"замка","label":"чол., знахідний","stress":"замка́"},{"form":"замок","label":"чол., знахідний"},{"form":"замкам","label":"множина, давальний"},{"form":"замки","label":"множина, кличний"},{"form":"замках","label":"множина, місцевий"},{"form":"замки","label":"множина, називний"},{"form":"замками","label":"множина, орудний"},{"form":"замків","label":"множина, родовий"},{"form":"замки","label":"множина, знахідний"}],"source":"VESUM","paradigm":{"kind":"noun","cases":{"називний":{"singular":"замок","plural":"замки"},"родовий":{"singular":"замка / замку","plural":"замків"},"давальний":{"singular":"замкові / замку","plural":"замкам"},"знахідний":{"singular":"замка / замок","plural":"замки"},"орудний":{"singular":"замком","plural":"замками"},"місцевий":{"singular":"замкові / замку","plural":"замках"},"кличний":{"singular":"замку","plural":"замки"}}},"stress":{"source":"ukrainian-word-stress","forms":{"замку":"за́мку","замка":"замка́","замка / замку":"замка́ / за́мку","замкові / замку":"замкові / за́мку","замка / замок":"замка́ / замок"}}},"meaning":{"definitions":["castle","lock"],"source":"kaikki/Wiktionary (CC BY-SA 3.0)","note":"English Wiktionary gloss fallback; direct per-lemma row."},"definition_cards":[{"id":"vts","source":"ВТС","source_pill":"ВТС","note":"Великий тлумачний словник сучасної української мови","definitions":["I з`амок-мка, ч. 1》 Укріплене житло феодала доби середньовіччя з оборонними, господарськими, культовими і т. ін. будівлями, зазвичай оточене високим кам'яним муром із кількома вежами. || Великий поміщицький будинок; палац. 2》 заст., рідко. Тюремна будівля; тюрма. II зам`ок-мка, ч. 1》 Пристрій для замикання дверей у приміщеннях, дверцят шафи, скринь, шухляд і т. ін. На замку бути — а) бути замкненим; б) бути недоступним для ворогів, добре охоронятися. Під замком бути (перебувати і т. ін.) — а) зберігатися замкненим (про цінності, харчові продукти і т. ін.); б) бути замкненим у якому-небудь приміщенні, ув'язненим. 2》 Застібка в намисті, браслеті. || Довга металева або пластмасова застібка для одягу, а також папок, портфелів і т. ін. 3》 У деяких видах вогнепальної зброї – пристрій, признач. для здійснення пострілу. 4》 тех. Пристрій для з'єднання рухомих частин механізму, машини і т. ін. 5》 З'єднані певним способом колоди, дерев'яні бруски. 6》 архіт. Центральний камінь арки. 7》 У системах обробки інформації – код, структура даних, програма або пристрій, що використовуються для керування доступом до даних або для синхронізації. || Операція, яка дозволяє лише одному процесу мати доступ до певного ресурсу. Замок захисту — програмний механізм перевірки паролів у випадку звертання до бази даних."],"source_url":"https://slovnyk.me/dict/vts/%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"}],"etymology":{"text":"Borrowed from Polish zamek (“castle”). From Proto-Slavic *zamъkъ, deverbal from *zamъknǫti.","source":"kaikki/Wiktionary (CC BY-SA 3.0)"},"literary_attestation":{"text":"…ювали метушню, піднімали правицю, мов для присяги, й заримованим експромтом (школа Теплухи, який кохався в римованих експромтах) пояснювали: даний картон — залізниця, Віндсорський замок, терми Каракалли, сад, гора, чи ще якась частина природи (бувало й таке, що картон втілював скупість, ревнощі, геніяльність, глупоту чи сумління, — Теплуха не відступав від засиди…","source":"literary_fts","source_label":"Андієвська Е. · Емма Андієвська. Роман про добру людину · 1931","chunk_id":"e4b5541c_c0272","source_url":""},"translation":{"en":["lock, locks","castle, castles","keystone (the top stone of an arch)"],"source":"learner_english_gloss","pos":"noun"},"sources":["Anna Ohoiko","PULS CEFR","VESUM","dmklinger","kaikki/Wiktionary (CC BY-SA 3.0)","learner_english_gloss","literary_fts","slovnyk.me: Словник синонімів Караванського","slovnyk.me: Фразеологічний словник української мови + Фразеологічний словник української мови","ВТС","Орфографічний словник української мови + Правописний словник Голоскевича (1929) + Орфоепічний словник української мови"],"examples":[{"uk":"У те́бе є велосипе́дний замо́к?","en":"Do you have a bicycle lock?","source":"Anna Ohoiko","locator":"ohoiko-1000-words entry 278"},{"uk":"У се́лі Свірж є старови́нний за́мок.","en":"In the village of Svirzh, there is an old castle.","source":"Anna Ohoiko","locator":"ohoiko-1000-words entry 277"}]},"entry_type":"lemma"},"aliases":[{"alias":"zamok","kind":"transliteration","source":"migration","target_slug":"замок"}],"relations":[],"provenance":[{"source_family":"built_vocabulary","source_locator":null,"extraction_mode":null}],"renderContext":{"componentLinks":[],"practiceLevels":["A2"]}}}]} satisfies { sourceVersion: string; generatedAt: string; manifestVersion: string; records: (Extract<EntryResult, {kind: "entry"}> & {record: {entry: Record<string, unknown>}})[] };
